Your current verifier will fail because `JSON.stringify(parsed)` changes the signed bytes.

Use **raw body bytes** and include the timestamp:

```ts
import crypto from 'node:crypto';

export function verifyStreamForgeWebhook(req: any, secret: string): boolean {
  const timestamp = req.headers['x-sf-timestamp'];
  const received = req.headers['x-sf-signature'];

  // req.rawBody must be captured before JSON parsing
  const payload = Buffer.concat([
    Buffer.from(String(timestamp)),
    Buffer.from('.'),
    req.rawBody
  ]);

  const expected = 'v1=' + crypto
    .createHmac('sha256', secret)
    .update(payload)
    .digest('hex');

  return crypto.timingSafeEqual(
    Buffer.from(expected),
    Buffer.from(String(received))
  );
}
```

Also enforce timestamp freshness:

- Reject if `abs(now - x-sf-timestamp) > 300s`
- Deduplicate on `x-sf-event-id`

