Here’s a compact `fetch` wrapper that respects `Retry-After` and adds jittered backoff:

```js
async function entitlementFetch(url, options, maxAttempts = 5) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const res = await fetch(url, options);

    if (res.status !== 429) {
      return res;
    }

    const retryAfter = Number(res.headers.get('retry-after') || 0);
    const baseDelayMs = retryAfter > 0 ? retryAfter * 1000 : Math.pow(2, attempt) * 250;
    const jitterMs = Math.floor(Math.random() * 300);
    const delayMs = baseDelayMs + jitterMs;

    if (attempt === maxAttempts) {
      throw new Error(`Entitlements API rate limited after ${maxAttempts} attempts`);
    }

    await new Promise(resolve => setTimeout(resolve, delayMs));
  }
}
```

